(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.HREngine=factory();})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';
  const playbooks=[
    {id:'payroll',name:'Payroll destination change',re:/(?:salary|payroll|direct deposit).{0,100}(?:bank|account|change|update)|(?:new|updated|change).{0,40}bank (?:details|account)/i,impact:'A changed destination could divert salary or a payment.',steps:['Confirm with the employee or vendor using the number already in the HR system.','Verify the destination through the approved payroll process.','Obtain the usual second approval before applying any change.']},
    {id:'recruitment',name:'Recruitment payment request',re:/(?:job|offer|recruit|interview|candidate|employment).{0,100}(?:fee|deposit|pay|gift card|crypto)|(?:pay|fee|deposit).{0,80}(?:job|offer|interview)/i,impact:'A payment request tied to recruitment can exploit someone seeking employment.',steps:['Check the recruiter and role through the organization’s independently located careers page.','Confirm the request with your established recruitment contact.','Do not approve a recruitment payment until its purpose and policy are independently verified.']},
    {id:'identity',name:'Sensitive identity or HR data request',re:/passport|social security|\bSSN\b|national (?:id|identity)|tax (?:id|number)|medical records?|bank statement/i,impact:'The request involves sensitive data. Legitimate HR workflows can also need these documents; this is a sensitivity flag, not proof of phishing.',steps:['Confirm why the data is needed and who is authorized to receive it.','Use the organization’s approved secure portal rather than an unexpected email destination.','Verify the requester through a known contact before sharing.']},
    {id:'access',name:'Account or benefits access request',re:/(?:benefit|onboard|HR portal|payroll).{0,100}(?:login|password|verif(?:y|ication)|code)|(?:login|password|verif(?:y|ication)|code).{0,100}(?:benefit|onboard|HR portal|payroll)|(?:send|share).{0,30}(?:password|OTP|one.time code)/i,impact:'An account-access request could expose workplace or payroll access.',steps:['Open the approved HR or benefits portal from your own bookmark.','Never disclose a password or one-time code.','Verify unexpected access requests with your usual IT or HR contact.']}
  ];
  function inspect(email){const text=String(email.subject||'')+'\n'+String(email.body||'');return playbooks.flatMap(p=>{const m=text.match(p.re);return m?[{id:p.id,name:p.name,impact:p.impact,evidence:m[0].slice(0,240),steps:[...p.steps]}]:[]});}
  function campaigns(emails){const groups=new Map();for(const e of emails){if(!e.assessment?.signals?.some(s=>s.weight>=20))continue;for(const host of new Set((e.assessment.links||[]).map(l=>l.host))){if(!host)continue;if(!groups.has(host))groups.set(host,[]);groups.get(host).push({id:e.id,subject:e.subject,source:e.source});}}return [...groups].filter(([,items])=>items.length>=2).map(([host,items])=>({host,count:items.length,messages:items,explanation:'Repeated destination across messages with supporting warning signals. This is a correlation clue; a shared legitimate service is a possible explanation.'}));}
  function incident(email,events=[]){return {product:'SignalGuard Desktop',version:'3.0.0',generatedAt:new Date().toISOString(),source:email.source,local:{level:email.assessment.level,index:email.assessment.score,engine:email.assessment.engine,signals:email.assessment.signals.map(s=>({id:s.id,title:s.title,weight:s.weight,category:s.category}))},sensitiveWorkflows:inspect(email).map(p=>({id:p.id,name:p.name,steps:p.steps})),ai:email.ai?{model:email.ai.model,severity:email.ai.severity,contractVersion:email.ai.contractVersion,consensus:email.aiMeta?.consensus}:null,review:events.map(x=>({at:x.at,type:x.type,stepId:x.stepId||null,checked:x.checked===true})),privacy:'Minimized export: no sender, subject, body, quotes, full URLs, or mailbox IDs. Review before sharing; categories and review times can still reveal context.',limitations:email.assessment.limitations};}
  return {inspect,campaigns,incident};
});
